import json
from collections import defaultdict


def load_invoices(path, month):
    with open(path, encoding="utf-8") as fh:
        records = json.load(fh)
    return [r for r in records if r["issued"].startswith(month)]


def group_by_customer(invoices):
    groups = defaultdict(list)
    for inv in invoices:
        groups[inv["customer"]].append(inv)
    return dict(groups)

