repo.README.md:
# cart-widgets

Small rendering helpers for the shop's cart drawer. Prices are integer cents throughout;
`formatPrice(cents, currency)` in `src/format.ts` turns them into display strings.

repo.src/format.ts:
// Display formatting for prices (amounts are integer cents).
const SYMBOLS: Record<string, string> = { USD: "$", EUR: "€", GBP: "£" };

export function formatPrice(cents: number, currency: string = "USD"): string {
  const symbol = SYMBOLS[currency] ?? `${currency} `;
  const sign = cents < 0 ? "-" : "";
  const abs = Math.abs(cents);
  const whole = Math.floor(abs / 100).toLocaleString("en-US");
  const fraction = String(abs % 100).padStart(2, "0");
  return `${sign}${symbol}${whole}.${fraction}`;
}

repo.src/cart.ts:
// Cart line items and totals.
export interface LineItem {
  sku: string;
  name: string;
  unitCents: number;
  quantity: number;
}

export function lineTotal(item: LineItem): number {
  return item.unitCents * item.quantity;
}

export function cartTotal(items: LineItem[]): number {
  return items.reduce((sum, item) => sum + lineTotal(item), 0);
}

repo.src/cartSummary.ts:
// Text rows for the cart drawer summary.
import { cartTotal, lineTotal, type LineItem } from "./cart.ts";
import { formatPrice } from "./format.ts";

export function summaryRows(items: LineItem[], currency: string): string[] {
  const rows = items.map(
    (item) => `${item.quantity} × ${item.name}  ${formatPrice(lineTotal(item), currency)}`,
  );
  rows.push(`Total  ${formatPrice(cartTotal(items), currency)}`);
  return rows;
}

repo.test/format.test.ts:
import { test } from "node:test";
import assert from "node:assert/strict";
import { formatPrice } from "../src/format.ts";

test("formats cents with two decimals", () => {
  assert.equal(formatPrice(1250), "$12.50");
  assert.equal(formatPrice(1200, "EUR"), "€12.00");
});

test("negative amounts keep the sign in front", () => {
  assert.equal(formatPrice(-399), "-$3.99");
});

repo.test/cartSummary.test.ts:
import { test } from "node:test";
import assert from "node:assert/strict";
import { summaryRows } from "../src/cartSummary.ts";

test("summary lists lines then the total", () => {
  const rows = summaryRows([{ sku: "T1", name: "Tea tin", unitCents: 600, quantity: 2 }], "USD");
  assert.deepEqual(rows, ["2 × Tea tin  $12.00", "Total  $12.00"]);
});

