import json
import urllib.request


def read_products(path):
    with open(path, encoding="utf-8") as fh:
        return [json.loads(line) for line in fh if line.strip()]


def batches(items, size):
    for start in range(0, len(items), size):
        yield items[start:start + size]


def push_batch(batch, settings):
    body = "\n".join(json.dumps(p) for p in batch).encode()
    req = urllib.request.Request(settings.endpoint, data=body, method="POST",
                                 headers={"Content-Type": "application/x-ndjson"})
    with urllib.request.urlopen(req, timeout=settings.timeout_seconds):
        pass


def run_sync(source, settings, push=push_batch):
    products = read_products(source)
    for batch in batches(products, settings.batch_size):
        push(batch, settings)
    return len(products)

