repo.src/mailer.ts:
// Outgoing mail over SMTP (connection settings come from the environment).
import { connect } from "node:net";

export interface Message {
  to: string;
  subject: string;
  body: string;
}

export function smtpSettings(env: Record<string, string | undefined> = process.env) {
  return {
    host: env.SMTP_HOST ?? "localhost",
    port: Number(env.SMTP_PORT ?? 25),
    from: env.MAIL_FROM ?? "no-reply@larkspur-news.example",
  };
}

export function renderMessage(msg: Message, from: string): string {
  return [`From: ${from}`, `To: ${msg.to}`, `Subject: ${msg.subject}`, "", msg.body, "."].join("\r\n");
}

export async function sendMail(msg: Message): Promise<void> {
  const { host, port, from } = smtpSettings();
  const lines = ["HELO larkspur", `MAIL FROM:<${from}>`, `RCPT TO:<${msg.to}>`, "DATA", renderMessage(msg, from), "QUIT"];
  await new Promise<void>((resolve, reject) => {
    const socket = connect(port, host);
    socket.on("error", reject);
    socket.on("connect", () => {
      socket.end(lines.join("\r\n") + "\r\n");
      resolve();
    });
  });
}

repo.src/signup.ts:
// Sign-up handling: validate the address and send the confirmation.
import { sendMail, type Message } from "./mailer.ts";

export function isValidEmail(address: string): boolean {
  return /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(address);
}

export async function registerSignup(
  address: string,
  send: (msg: Message) => Promise<void> = sendMail,
): Promise<boolean> {
  if (!isValidEmail(address)) return false;
  await send({ to: address, subject: "Confirm your subscription", body: "Click the link to confirm." });
  return true;
}

repo.src/server.ts:
// HTTP entry point.
import { createServer } from "node:http";
import { registerSignup } from "./signup.ts";

const server = createServer(async (req, res) => {
  if (req.method === "POST" && req.url === "/signup") {
    let body = "";
    for await (const chunk of req) body += chunk;
    const ok = await registerSignup(new URLSearchParams(body).get("email") ?? "");
    res.writeHead(ok ? 202 : 400).end();
    return;
  }
  res.writeHead(404).end();
});

server.listen(Number(process.env.PORT ?? 3000));

repo.test/signup.test.ts:
import { test } from "node:test";
import assert from "node:assert/strict";
import { registerSignup } from "../src/signup.ts";
import { renderMessage } from "../src/mailer.ts";

test("rejects malformed addresses without sending", async () => {
  let sent = 0;
  assert.equal(await registerSignup("not-an-email", async () => { sent++; }), false);
  assert.equal(sent, 0);
});

test("renders headers before the body", () => {
  const text = renderMessage({ to: "a@b.example", subject: "Hi", body: "Body" }, "x@y.example");
  assert.ok(text.startsWith("From: x@y.example\r\nTo: a@b.example"));
});

