repo.tests/test_limiter.py:
from throttle.limiter import RateLimiter


class FakeClock:
    def __init__(self):
        self.now = 0.0

    def __call__(self):
        return self.now

    def sleep(self, seconds):
        self.now += seconds


def test_first_requests_do_not_wait():
    clock = FakeClock()
    limiter = RateLimiter(rate=5, clock=clock, sleep=clock.sleep)
    for _ in range(5):
        limiter.acquire()
    assert clock.now == 0.0


def test_request_over_the_rate_waits():
    clock = FakeClock()
    limiter = RateLimiter(rate=5, clock=clock, sleep=clock.sleep)
    for _ in range(6):
        limiter.acquire()
    assert clock.now > 0

