repo.scripts/build-sitemap.ts:
// Writes sitemap.xml for the published pages.
import { parseArgs } from "node:util";
import { mkdirSync, writeFileSync } from "node:fs";
import { dirname } from "node:path";
import { pages } from "../src/pages.ts";
import { renderSitemap } from "../src/sitemap.ts";

const { values } = parseArgs({
  options: {
    "base-url": { type: "string" },
    out: { type: "string", default: "dist/sitemap.xml" },
  },
});

const baseUrl = values["base-url"];
if (!baseUrl) {
  console.error("--base-url is required");
  process.exit(2);
}

const published = pages.filter((page) => !page.draft);
mkdirSync(dirname(values.out), { recursive: true });
writeFileSync(values.out, renderSitemap(baseUrl, published));
console.log(`wrote ${published.length} urls to ${values.out}`);

