// Page registry for the site.
export interface Page {
  path: string;
  title: string;
  updated: string;
  draft: boolean;
}

export const pages: Page[] = [
  { path: "/", title: "Home", updated: "2026-10-01", draft: false },
  { path: "/visit", title: "Plan your visit", updated: "2026-09-12", draft: false },
  { path: "/events/winter-lights", title: "Winter Lights", updated: "2026-11-02", draft: true },
  { path: "/membership", title: "Membership", updated: "2026-08-20", draft: false },
];

repo.src/sitemap.ts:
// Sitemap XML rendering.
import type { Page } from "./pages.ts";

export function renderSitemap(baseUrl: string, pages: Page[]): string {
  const base = baseUrl.replace(/\/$/, "");
  const urls = pages
    .map((p) => `  <url><loc>${base}${p.path}</loc><lastmod>${p.updated}</lastmod></url>`)
    .join("\n");
  return `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${urls}\n</urlset>\n`;
}

