// Loads notify.config.json.
import { readFileSync } from "node:fs";

export interface NotifyConfig {
  channels: string[];
  maxPerHour: number;
  defaultLocale: string;
}

export function loadConfig(path = "notify.config.json"): NotifyConfig {
  const raw = JSON.parse(readFileSync(path, "utf8"));
  return {
    channels: raw.channels ?? ["push"],
    maxPerHour: raw.maxPerHour ?? 4,
    defaultLocale: raw.defaultLocale ?? "en-GB",
  };
}

repo.src/notifier.ts:
// Decides whether a notification goes out and on which channels.
import type { NotifyConfig } from "./config.ts";

export interface Notice {
  userId: string;
  text: string;
  at: Date;
}

export class Notifier {
  private config: NotifyConfig;
  private sent = new Map<string, number[]>();

  constructor(config: NotifyConfig) {
    this.config = config;
  }

  channelsFor(notice: Notice): string[] {
    const hourAgo = notice.at.getTime() - 3_600_000;
    const recent = (this.sent.get(notice.userId) ?? []).filter((t) => t > hourAgo);
    if (recent.length >= this.config.maxPerHour) return [];
    recent.push(notice.at.getTime());
    this.sent.set(notice.userId, recent);
    return this.config.channels;
  }
}

repo.src/main.ts:
// Entry point: reads queued notices from stdin, one JSON object per line.
import { createInterface } from "node:readline";
import { loadConfig } from "./config.ts";
import { Notifier } from "./notifier.ts";

const notifier = new Notifier(loadConfig());
for await (const line of createInterface({ input: process.stdin })) {
  const notice = JSON.parse(line);
  const channels = notifier.channelsFor({ ...notice, at: new Date(notice.at) });
  console.log(JSON.stringify({ userId: notice.userId, channels }));
}

