import assert from "node:assert/strict";
import { Notifier } from "../src/notifier.ts";

const config = { channels: ["push"], maxPerHour: 2, defaultLocale: "en-GB" };

test("caps notifications per user per hour", () => {
  const n = new Notifier(config);
  const at = new Date("2026-11-01T10:00:00Z");
  assert.deepEqual(n.channelsFor({ userId: "u1", text: "a", at }), ["push"]);
  assert.deepEqual(n.channelsFor({ userId: "u1", text: "b", at }), ["push"]);
  assert.deepEqual(n.channelsFor({ userId: "u1", text: "c", at }), []);
});

