// Forecast provider calls.
import { HttpClient } from "./http.ts";

export interface DailyForecast {
  date: string;
  highC: number;
  lowC: number;
}

export function createWeatherApi(apiKey: string, fetchImpl?: typeof fetch) {
  const client = new HttpClient({
    baseUrl: "https://api.nimbus-forecast.example/v1",
    timeoutMs: 3000,
    headers: { "X-Api-Key": apiKey },
    fetchImpl,
  });
  return {
    daily(city: string): Promise<DailyForecast[]> {
      return client.getJson<DailyForecast[]>(`/daily?city=${encodeURIComponent(city)}`);
    },
  };
}

