import { test } from "node:test";
import assert from "node:assert/strict";
import { createWeatherApi } from "../src/weatherApi.ts";

test("encodes the city and sends the api key", async () => {
  let seen: { url: string; key: string | null } | undefined;
  const fakeFetch = (async (url: string, init: RequestInit) => {
    seen = { url, key: new Headers(init.headers).get("X-Api-Key") };
    return Response.json([]);
  }) as unknown as typeof fetch;
  await createWeatherApi("k-123", fakeFetch).daily("São Paulo");
  assert.equal(seen?.url, "https://api.nimbus-forecast.example/v1/daily?city=S%C3%A3o%20Paulo");
  assert.equal(seen?.key, "k-123");
});

