@dataclass(frozen=True)
class ReportSettings:
    title: str = "Report"
    theme: str = "plain"
    output_dir: str = "site"


def load_settings(pyproject=Path("pyproject.toml")):
    with open(pyproject, "rb") as fh:
        table = tomllib.load(fh).get("tool", {}).get("reportgen", {})
    return ReportSettings(
        title=table.get("title", ReportSettings.title),
        theme=table.get("theme", ReportSettings.theme),
        output_dir=table.get("output_dir", ReportSettings.output_dir),
    )

