import html
from pathlib import Path

THEMES = {
    "plain": "body{font-family:serif;max-width:46em;margin:auto}",
    "dark": "body{background:#111;color:#eee;font-family:sans-serif}",
}


def read_sections(directory):
    sections = []
    for path in sorted(Path(directory).glob("*.txt")):
        heading, _, body = path.read_text(encoding="utf-8").partition("\n")
        sections.append((heading.strip(), body.strip()))
    return sections


def render_report(settings, sections):
    parts = [f"<h1>{html.escape(settings.title)}</h1>"]
    for heading, body in sections:
        parts.append(f"<h2>{html.escape(heading)}</h2>")
        parts.extend(f"<p>{html.escape(p)}</p>" for p in body.split("\n\n") if p)
    style = THEMES.get(settings.theme, THEMES["plain"])
    return f"<!doctype html><style>{style}</style>\n" + "\n".join(parts) + "\n"

