// Leveled console logger; LOG_LEVEL picks the threshold.
const LEVELS = ["debug", "info", "warn", "error"] as const;
type Level = (typeof LEVELS)[number];

export function createLogger(env: Record<string, string | undefined> = process.env) {
  const threshold = LEVELS.indexOf((env.LOG_LEVEL ?? "info") as Level);
  const emit = (level: Level, message: string) => {
    if (LEVELS.indexOf(level) < threshold) return;
    console.log(`${new Date().toISOString()} ${level.toUpperCase()} ${message}`);
  };
  return {
    debug: (m: string) => emit("debug", m),
    info: (m: string) => emit("info", m),
    warn: (m: string) => emit("warn", m),
    error: (m: string) => emit("error", m),
  };
}

repo.src/returns.ts:
// Return requests: eligible within 30 days of delivery.
export interface ReturnRequest {
  orderId: string;
  deliveredOn: string;
  reason: string;
}

export function isEligible(req: ReturnRequest, today: Date): boolean {
  const delivered = new Date(`${req.deliveredOn}T00:00:00Z`);
  const days = (today.getTime() - delivered.getTime()) / 86_400_000;
  return days >= 0 && days <= 30;
}

repo.src/server.ts:
// HTTP entry point for the returns API.
import { createServer } from "node:http";
import { createLogger } from "./logger.ts";
import { isEligible } from "./returns.ts";

const log = createLogger();

createServer(async (req, res) => {
  if (req.method === "POST" && req.url === "/returns") {
    let body = "";
    for await (const chunk of req) body += chunk;
    const request = JSON.parse(body);
    const ok = isEligible(request, new Date());
    log.info(`return ${request.orderId} eligible=${ok}`);
    res.writeHead(ok ? 201 : 422).end();
    return;
  }
  res.writeHead(404).end();
}).listen(Number(process.env.PORT ?? 8080));

