import { test } from "node:test";
import assert from "node:assert/strict";
import { isEligible } from "../src/returns.ts";

test("thirty days after delivery is still eligible", () => {
  const req = { orderId: "R1", deliveredOn: "2026-10-01", reason: "size" };
  assert.equal(isEligible(req, new Date("2026-10-31T00:00:00Z")), true);
  assert.equal(isEligible(req, new Date("2026-11-01T00:00:01Z")), false);
});

