repo.shipping/batch.py:
import json
from pathlib import Path

from .labels import render_label
from .models import Address, Parcel


def load_queue(path):
    data = json.loads(Path(path).read_text(encoding="utf-8"))
    return [Parcel(tracking=p["tracking"], weight_g=p["weight_g"], recipient=Address(**p["recipient"]))
            for p in data]


def render_batch(queue_path, out_dir):
    out = Path(out_dir)
    out.mkdir(parents=True, exist_ok=True)
    parcels = load_queue(queue_path)
    for parcel in parcels:
        (out / f"{parcel.tracking}.txt").write_text(render_label(parcel) + "\n", encoding="utf-8")
    return len(parcels)

