import json
import os
import time
import urllib.request


class FeedPoller:
    def __init__(self, env=None, fetch=None, sleep=time.sleep):
        env = os.environ if env is None else env
        self.url = env["FEED_URL"]
        self.interval = float(env.get("FEED_POLL_INTERVAL", "60"))
        self._fetch = fetch or self._http_get
        self._sleep = sleep
        self._last = None

    def _http_get(self, url):
        with urllib.request.urlopen(url, timeout=15) as resp:
            return json.load(resp)

    def poll_once(self):
        prices = self._fetch(self.url)
        changed = {} if self._last is None else {
            sku: price for sku, price in prices.items() if self._last.get(sku) != price
        }
        self._last = prices
        return changed

    def run(self, handle, cycles=None):
        count = 0
        while cycles is None or count < cycles:
            handle(self.poll_once())
            count += 1
            self._sleep(self.interval)

