from poller.feed import FeedPoller


def test_reports_only_changed_prices():
    snapshots = iter([{"A": 100, "B": 200}, {"A": 100, "B": 250}])
    poller = FeedPoller(env={"FEED_URL": "http://feed"}, fetch=lambda url: next(snapshots), sleep=lambda s: None)
    assert poller.poll_once() == {}
    assert poller.poll_once() == {"B": 250}


def test_interval_comes_from_env():
    poller = FeedPoller(env={"FEED_URL": "http://feed", "FEED_POLL_INTERVAL": "15"}, fetch=dict, sleep=lambda s: None)
    assert poller.interval == 15.0

