repo.README.md:
# orders-admin

Internal admin API for the order desk. `src/csv.ts` is our small CSV module (`toCsv(rows, columns)`);
the export routes live in `src/routes/`.

repo.src/csv.ts:
// Small CSV writer (RFC 4180 quoting, CRLF line endings).
export interface Column<T> {
  header: string;
  value: (row: T) => string | number;
}

function quote(field: string): string {
  return /[",\r\n]/.test(field) ? `"${field.replaceAll('"', '""')}"` : field;
}

export function toCsv<T>(rows: T[], columns: Column<T>[]): string {
  const lines = [columns.map((c) => quote(c.header)).join(",")];
  for (const row of rows) {
    lines.push(columns.map((c) => quote(String(c.value(row)))).join(","));
  }
  return lines.join("\r\n") + "\r\n";
}

repo.src/orders.ts:
// Order records as stored by the order desk.
export interface Order {
  id: string;
  customer: string;
  city: string;
  totalCents: number;
  placedAt: string;
}

export const sampleOrders: Order[] = [
  { id: "O-1001", customer: "Zoë Marchetti", city: "Sète", totalCents: 4590, placedAt: "2026-11-02" },
  { id: "O-1002", customer: "Jonas Lindqvist", city: "Malmö", totalCents: 1299, placedAt: "2026-11-03" },
];

repo.src/routes/exportOrders.ts:
// GET /orders.csv: the order list as a CSV download.
import type { IncomingMessage, ServerResponse } from "node:http";
import { toCsv } from "../csv.ts";
import { type Order, sampleOrders } from "../orders.ts";

export function exportOrders(_req: IncomingMessage, res: ServerResponse, orders: Order[] = sampleOrders): void {
  const body = toCsv(orders, [
    { header: "Order", value: (o) => o.id },
    { header: "Customer", value: (o) => o.customer },
    { header: "City", value: (o) => o.city },
    { header: "Total", value: (o) => (o.totalCents / 100).toFixed(2) },
    { header: "Placed", value: (o) => o.placedAt },
  ]);
  res.writeHead(200, {
    "Content-Type": "text/csv; charset=utf-8",
    "Content-Disposition": "attachment; filename=orders.csv",
  });
  res.end(body);
}

