import { toCsv } from "../src/csv.ts";

test("quotes fields with commas and quotes", () => {
  const csv = toCsv([{ name: 'Ruth "Ru" Okafor, Ltd' }], [{ header: "Name", value: (r) => r.name }]);
  assert.equal(csv, 'Name\r\n"Ruth ""Ru"" Okafor, Ltd"\r\n');
});

