// Converts old storefront orders into the new order-store shape.
import { readFileSync, renameSync, writeFileSync } from "node:fs";

export interface OldOrder {
  order_no: number;
  buyer: string;
  amount: string;
}

export interface NewOrder {
  id: string;
  customer: string;
  totalCents: number;
}

export function convertId(orderNo: number): string {
  return `ORD-${orderNo.toString(36).toUpperCase()}`;
}

export function convert(order: OldOrder): NewOrder {
  return { id: convertId(order.order_no), customer: order.buyer, totalCents: Math.round(Number(order.amount) * 100) };
}

export function migrateFile(from: string, to: string): number {
  const orders: OldOrder[] = JSON.parse(readFileSync(from, "utf8"));
  const tmp = `${to}.tmp`;
  writeFileSync(tmp, JSON.stringify(orders.map(convert), null, 2));
  renameSync(tmp, to);
  return orders.length;
}

