import configparser
from dataclasses import dataclass

SEVERITIES = ["info", "warning", "error", "critical"]


@dataclass(frozen=True)
class Alert:
    team: str
    severity: str
    summary: str


class AlertRouter:
    def __init__(self, config_path="alerts.ini"):
        parser = configparser.ConfigParser()
        parser.read(config_path)
        self.teams = {
            name: {
                "channel": section.get("channel"),
                "threshold": section.get("severity_threshold", "warning"),
            }
            for name, section in parser.items()
            if name != "DEFAULT"
        }

    def route(self, alert):
        team = self.teams.get(alert.team)
        if team is None:
            return None
        if SEVERITIES.index(alert.severity) < SEVERITIES.index(team["threshold"]):
            return None
        return team["channel"]

