// Sample data for local development.
import { readFileSync } from "node:fs";
import { join } from "node:path";

export interface Fixtures {
  users: { id: string; name: string }[];
  recipes: { id: string; title: string; authorId: string }[];
  photos: { recipeId: string; bytes: number }[];
}

export function loadFixtures(dir = "fixtures"): Fixtures {
  const read = (name: string) => JSON.parse(readFileSync(join(dir, name), "utf8"));
  const photos = read("photos.json").map((p: { recipeId: string; file: string }) => ({
    recipeId: p.recipeId,
    bytes: readFileSync(join(dir, "media", p.file)).length,
  }));
  return { users: read("users.json"), recipes: read("recipes.json"), photos };
}

