repo.README.md:
# quill-blog

Blog engine for the Quill & Ember bookshop. Post URLs are `/blog/<year>/<month>/<slug>`;
slugs come from `slugify(title, options)` in `src/slug.ts`.

repo.src/slug.ts:
// URL slugs from titles.
export interface SlugOptions {
  maxLength?: number;
  separator?: string;
}

export function slugify(title: string, options: SlugOptions = {}): string {
  const { maxLength = Infinity, separator = "-" } = options;
  const slug = title
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, separator)
    .split(separator)
    .filter(Boolean)
    .join(separator);
  if (slug.length <= maxLength) return slug;
  const cut = slug.slice(0, maxLength);
  const lastSep = cut.lastIndexOf(separator);
  return lastSep > 0 ? cut.slice(0, lastSep) : cut;
}

