// Blog post records and their public URLs.
import { slugify } from "./slug.ts";

export interface Post {
  id: number;
  title: string;
  publishedOn: string;
}

export function postUrl(post: Post): string {
  const [year, month] = post.publishedOn.split("-");
  return `/blog/${year}/${month}/${slugify(post.title)}`;
}

