import tomllib
from dataclasses import dataclass
from pathlib import Path

DEFAULT_PATH = Path(__file__).resolve().parents[1] / "config" / "app.toml"


@dataclass(frozen=True)
class Settings:
    database_url: str
    cache_ttl_seconds: int = 60


def load_settings(env, path=DEFAULT_PATH):
    with open(path, "rb") as fh:
        table = tomllib.load(fh)[env]
    return Settings(
        database_url=table["database_url"],
        cache_ttl_seconds=int(table.get("cache_ttl_seconds", 60)),
    )

repo.menu/cache.py:
import time


class TTLCache:
    def __init__(self, ttl_seconds, clock=time.monotonic):
        self.ttl = ttl_seconds
        self._clock = clock
        self._items = {}

    def get(self, key):
        hit = self._items.get(key)
        if hit is None or self._clock() - hit[1] > self.ttl:
            return None
        return hit[0]

    def put(self, key, value):
        self._items[key] = (value, self._clock())

