// Worker settings from the environment.
export function workerConfig(env: Record<string, string | undefined> = process.env) {
  const concurrency = Number.parseInt(env.QUEUE_CONCURRENCY ?? "2", 10);
  return {
    redisUrl: env.REDIS_URL ?? "redis://localhost:6379",
    concurrency: Number.isFinite(concurrency) && concurrency > 0 ? concurrency : 2,
  };
}

