import secrets
import time


class SessionStore:
    """In-memory sessions that expire `max_age_seconds` after creation."""

    def __init__(self, max_age_seconds=86400, clock=time.time):
        self.max_age_seconds = max_age_seconds
        self._clock = clock
        self._sessions = {}

    def create(self, user_id):
        token = secrets.token_urlsafe(24)
        self._sessions[token] = (user_id, self._clock())
        return token

    def user_for(self, token):
        entry = self._sessions.get(token)
        if entry is None:
            return None
        user_id, created = entry
        if self._clock() - created > self.max_age_seconds:
            del self._sessions[token]
            return None
        return user_id

