// CSV rows (sku,name,price,image_url) to product records.
export interface Product {
  sku: string;
  name: string;
  priceCents: number;
  imageUrl: string;
}

export function parseProducts(csv: string): Product[] {
  const [, ...rows] = csv.trim().split(/\r?\n/);
  return rows.map((row) => {
    const [sku, name, price, imageUrl] = row.split(",");
    return { sku, name, priceCents: Math.round(Number(price) * 100), imageUrl };
  });
}

