// Downloads product images into public/images/.
import { mkdirSync, writeFileSync } from "node:fs";
import type { Product } from "./products.ts";

export async function downloadImages(products: Product[]): Promise<void> {
  mkdirSync("public/images", { recursive: true });
  for (const product of products) {
    const res = await fetch(product.imageUrl);
    writeFileSync(`public/images/${product.sku}.jpg`, Buffer.from(await res.arrayBuffer()));
  }
}

