repo.tidewatch/predict.py:
import math
from dataclasses import dataclass


@dataclass(frozen=True)
class Constituent:
    name: str
    amplitude_m: float
    speed_deg_per_hour: float
    phase_deg: float


def height_at(hours, constituents, mean_level_m=0.0):
    total = mean_level_m
    for c in constituents:
        total += c.amplitude_m * math.cos(math.radians(c.speed_deg_per_hour * hours - c.phase_deg))
    return total

