// Unit conversions for the recipe scaler.
const GRAMS_PER: Record<string, number> = { g: 1, kg: 1000, oz: 28.3495, lb: 453.592 };

export function toGrams(amount: number, unit: string): number {
  const factor = GRAMS_PER[unit];
  if (factor === undefined) throw new Error(`unknown unit: ${unit}`);
  return amount * factor;
}

