from datetime import datetime, timedelta

ZONE_RATES_CENTS = {"A": 400, "B": 250, "C": 120}


def charge_cents(zone, start: datetime, end: datetime):
    if end <= start:
        raise ValueError("end must be after start")
    hours = (end - start) / timedelta(hours=1)
    started_hours = int(hours) + (0 if hours.is_integer() else 1)
    return started_hours * ZONE_RATES_CENTS[zone]

