// Aggregates component checks into an overall status.
export type Health = "up" | "degraded" | "down";

export function overall(checks: Record<string, Health>): Health {
  const values = Object.values(checks);
  if (values.includes("down")) return "down";
  if (values.includes("degraded")) return "degraded";
  return "up";
}

