// Delivery zones by distance from the depot.
import { distanceKm, type Point } from "./geo.ts";

export const DEPOT: Point = { lat: 51.4545, lon: -2.5879 };

export function zoneFor(address: Point): "A" | "B" | "C" | null {
  const km = distanceKm(DEPOT, address);
  if (km <= 5) return "A";
  if (km <= 15) return "B";
  if (km <= 40) return "C";
  return null;
}

