from dataclasses import dataclass
from datetime import date


@dataclass(frozen=True)
class Stay:
    pet: str
    run: int
    arrive: date
    leave: date


def overlaps(a: Stay, b: Stay) -> bool:
    return a.run == b.run and a.arrive < b.leave and b.arrive < a.leave


def can_book(new: Stay, existing: list[Stay]) -> bool:
    return new.leave > new.arrive and not any(overlaps(new, s) for s in existing)

