// Checkout totals for a basket.
import { vatFor } from "./tax.ts";

export interface BasketLine {
  category: string;
  netCents: number;
  qty: number;
}

export function checkoutTotal(lines: BasketLine[]): { net: number; vat: number; gross: number } {
  let net = 0;
  let vat = 0;
  for (const line of lines) {
    net += line.netCents * line.qty;
    vat += vatFor(line.category, line.netCents) * line.qty;
  }
  return { net, vat, gross: net + vat };
}

