def vent_opening(temp_c, target_c=24.0, full_open_at=6.0):
    """Fraction (0..1) the roof vents open for the current temperature."""
    excess = temp_c - target_c
    if excess <= 0:
        return 0.0
    return min(1.0, excess / full_open_at)


