// Hours per project for one month.
export interface Entry {
  date: string;
  project: string;
  hours: number;
}

export function summarize(entries: Entry[], month: string): Record<string, number> {
  const totals: Record<string, number> = {};
  for (const e of entries) {
    if (!e.date.startsWith(month)) continue;
    totals[e.project] = (totals[e.project] ?? 0) + e.hours;
  }
  return totals;
}

export function toTable(totals: Record<string, number>): string {
  return Object.entries(totals)
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([project, hours]) => `${project.padEnd(20)} ${hours.toFixed(1).padStart(6)}`)
    .join("\n");
}

