// Upload size checks.
const MAX_BYTES = 10 * 1024 * 1024;

export function checkUpload(sizeBytes: number): { ok: true } | { ok: false; status: 413; message: string } {
  if (sizeBytes > MAX_BYTES) {
    return { ok: false, status: 413, message: `uploads are limited to ${MAX_BYTES / 1024 / 1024} MB` };
