// Accepts PUT /drawings/<name> uploads.
import { createServer } from "node:http";
import { checkUpload } from "./upload.ts";

createServer((req, res) => {
  const verdict = checkUpload(Number(req.headers["content-length"] ?? 0));
  if (!verdict.ok) {
    res.writeHead(verdict.status).end(verdict.message);
    return;
  }
  req.resume();
  req.on("end", () => res.writeHead(201).end());
}).listen(Number(process.env.PORT ?? 8080));

