import requests


def check_link(url, session=None):
    """Return (url, status_code) for one link."""
    session = session or requests.Session()
    response = session.head(url, timeout=10)
    return url, response.status_code


def classify(status):
    if status >= 400:
        return "broken"
    if 300 <= status < 400:
        return "moved"
    return "ok"

