// Parses the bank-statement CSV export.
export interface ParseOptions {
  strictDates?: boolean;
  delimiter?: string;
}

export interface Row {
  date: Date;
  description: string;
  amountCents: number;
}

function parseDate(text: string, strict: boolean): Date {
  const [y, m, d] = text.split("-").map(Number);
  const date = new Date(Date.UTC(y, m - 1, d));
  if (strict && (date.getUTCMonth() !== m - 1 || date.getUTCDate() !== d)) {
    throw new Error(`invalid date: ${text}`);
  }
  return date;
}

export function parseCsv(text: string, options: ParseOptions = {}): Row[] {
  const { strictDates = false, delimiter = "," } = options;
  return text.trim().split(/\r?\n/).slice(1).map((line) => {
    const [date, description, amount] = line.split(delimiter);
    return { date: parseDate(date, strictDates), description, amountCents: Math.round(Number(amount) * 100) };
  });
}

