MAX_RATE = 0.25
TIERS = [(100, 0.15), (50, 0.10), (10, 0.05)]


def tier_rate(quantity):
    return next((rate for minimum, rate in TIERS if quantity >= minimum), 0.0)


def bulk_rate(quantity, loyalty_bonus=0.0):
    """Tier rate plus loyalty bonus, capped at MAX_RATE."""
    return min(tier_rate(quantity), MAX_RATE) + loyalty_bonus


def discounted_cents(unit_cents, quantity, loyalty_bonus=0.0):
    return round(unit_cents * quantity * (1 - bulk_rate(quantity, loyalty_bonus)))

