// Combines standalone SVG icons into one sprite of <symbol> elements.
export interface Icon {
  id: string;
  svg: string;
}

export function toSymbol(icon: Icon): string {
  const viewBox = /viewBox="([^"]+)"/.exec(icon.svg)?.[1] ?? "0 0 24 24";
  const inner = icon.svg.replace(/^[\s\S]*?<svg[^>]*>/, "").replace(/<\/svg>\s*$/, "");
  return `<symbol id="${icon.id}" viewBox="${viewBox}">${inner}</symbol>`;
}

export function buildSprite(icons: Icon[]): string {
  return `<svg xmlns="http://www.w3.org/2000/svg" style="display:none">${icons.map(toSymbol).join("")}</svg>\n`;
}

