import logging

log = logging.getLogger("roster-sync")


def run_sync(source, target, verbose=False):
    """Copy changed roster entries from source to target (dict-like stores)."""
    if verbose:
        logging.basicConfig(level=logging.DEBUG)
    changed = 0
    for key, value in source.items():
        if target.get(key) != value:
            target[key] = value
            changed += 1
            if verbose:
                log.debug("updated %s", key)
    log.info("sync finished: %d changed", changed)
    return changed

