// File listing helpers for the docs deploy.
import { readdirSync } from "node:fs";
import { join, relative } from "node:path";

export function listFiles(root: string, dir: string = root): string[] {
  return readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
    const full = join(dir, entry.name);
    return entry.isDirectory() ? listFiles(root, full) : [relative(root, full)];
  });
}

export function stale(local: string[], remote: string[]): string[] {
  const keep = new Set(local);
  return remote.filter((f) => !keep.has(f));
}

