import os
from datetime import datetime, time, timedelta
from zoneinfo import ZoneInfo


def report_zone(env=None):
    env = os.environ if env is None else env
    return ZoneInfo(env.get("REPORT_TIMEZONE", "UTC"))


def next_run(now_utc, at=time(7, 0), env=None):
    zone = report_zone(env)
    local = now_utc.astimezone(zone)
    candidate = datetime.combine(local.date(), at, tzinfo=zone)
    if candidate <= local:
        candidate = datetime.combine(local.date() + timedelta(days=1), at, tzinfo=zone)
    return candidate

