// Client for the product catalogue service.
export interface CatalogClientOptions {
  baseUrl: string;
  cacheResponses?: boolean;
  fetchImpl?: typeof fetch;
}

export class CatalogClient {
  private baseUrl: string;
  private cache: Map<string, unknown> | null;
  private fetchImpl: typeof fetch;

  constructor(options: CatalogClientOptions) {
    this.baseUrl = options.baseUrl;
    this.cache = options.cacheResponses ? new Map() : null;
    this.fetchImpl = options.fetchImpl ?? fetch;
  }

  async product(sku: string): Promise<unknown> {
    const url = `${this.baseUrl}/products/${encodeURIComponent(sku)}`;
    if (this.cache?.has(url)) return this.cache.get(url);
    const res = await this.fetchImpl(url);
    if (!res.ok) throw new Error(`catalogue returned ${res.status}`);
    const body = await res.json();
    this.cache?.set(url, body);
    return body;
  }
}

