def keep_attachments(attachments, settings):
    """Attachments within the size limit, at most settings.max_attachments of them."""
    limit = settings.max_attachment_mb * 1024 * 1024
    small = [a for a in attachments if a["size"] <= limit]
    return small[: settings.max_attachments]


def to_ticket(email, settings):
    return {
        "subject": email["subject"],
        "from": email["from"],
        "attachments": [a["name"] for a in keep_attachments(email.get("attachments", []), settings)],
    }
